package org.eclipse.rdf4j.sail.lmdb;

/**
 * Predicate-wide {@link RecordIterator} over one complete outgoing adjacency plane. Keys and runs are both unsigned
 * ordered, so iteration produces the same subject-major order as the LMDB {@code spoc} index without materializing the
 * predicate's rows. The composed adjacency view owns base/delta key-domain merging; this cursor only walks that domain
 * and bulk-decodes each resolved run.
 */
final class LmdbDirectAdjacencyRootIterator implements RecordIterator {

	private static final int COPY_EDGES = 256;

	private LmdbAdjacencyReadView view;
	private final LmdbDirectNativeAdjacency.RootScanCursor cursor;
	private final long predicate;
	private long key;
	private long runOffset;
	private long runSize;
	private final long[] quad = new long[4];
	private long[] neighbors;
	private long[] contexts;

	LmdbDirectAdjacencyRootIterator(LmdbAdjacencyReadView view, LmdbDirectNativeAdjacency adjacency,
			long predicate) {
		view.retainLease();
		boolean initialized = false;
		try {
			this.view = view;
			this.cursor = adjacency.rootScanCursor();
			this.predicate = predicate;
			initialized = true;
		} finally {
			if (!initialized) {
				view.releaseLease();
			}
		}
	}

	@Override
	public String getIndexName() {
		return "direct-spoc";
	}

	private boolean advanceRun() {
		while (runOffset >= runSize) {
			if (!cursor.advance()) {
				return false;
			}
			key = cursor.key();
			runOffset = 0L;
			runSize = cursor.size();
		}
		return true;
	}

	@Override
	public long[] next() {
		if (!advanceRun()) {
			return null;
		}
		quad[TripleIndex.SUBJ_IDX] = key;
		quad[TripleIndex.PRED_IDX] = predicate;
		quad[TripleIndex.OBJ_IDX] = cursor.neighborAt(runOffset);
		quad[TripleIndex.CONTEXT_IDX] = cursor.contextAt(runOffset);
		runOffset++;
		return quad;
	}

	@Override
	public int fill(long[] buffer, int maxRows) {
		int rows = 0;
		while (rows < maxRows && advanceRun()) {
			int copied = (int) Math.min(Math.min((long) COPY_EDGES, maxRows - rows), runSize - runOffset);
			ensureScratch(copied);
			int pairCount = cursor.copyPairs(runOffset, copied, neighbors, contexts);
			if (pairCount != copied) {
				throw new IllegalStateException("adjacency run ended during root-scan decode");
			}
			for (int index = 0; index < copied; index++) {
				int base = (rows + index) * 4;
				buffer[base + TripleIndex.SUBJ_IDX] = key;
				buffer[base + TripleIndex.PRED_IDX] = predicate;
				buffer[base + TripleIndex.OBJ_IDX] = neighbors[index];
				buffer[base + TripleIndex.CONTEXT_IDX] = contexts[index];
			}
			runOffset += copied;
			rows += copied;
		}
		return rows;
	}

	private void ensureScratch(int length) {
		if (neighbors == null || neighbors.length < length) {
			neighbors = new long[length];
			contexts = new long[length];
		}
	}

	@Override
	public void close() {
		LmdbAdjacencyReadView owned = view;
		if (owned != null) {
			view = null;
			owned.releaseLease();
		}
	}
}
